<template>
    <div>
        <label for="filterReview">Filter</label>
        <select id="filterReview" v-model="selectedRating">
            <option value="">all</option>
            <option value="5">5</option>
            <option value="4">4</option>
            <option value="3">3</option>
            <option value="2">2</option>
            <option value="1">1</option>
        </select>
        <table>
            <thead>
                <tr>
                    <th>Name</th>
                    <th>Rating</th>
                    <th>Coment</th>
                </tr>
            </thead>
            <tbody>
                <tr v-for="(review, index) in filteredReviews" :key="index">
                    <td>{{ review.Name }}</td>
                    <td>{{ review.Rating }}</td>
                    <td class="comment">{{ review.Comment }}</td>
                </tr>
            </tbody>
        </table>
    </div>
</template>

<script>
import Papa from 'papaparse';

export default {
    name: "ReviewsComponent",
    data() {
        return {
            reviews: [],
            selectedRating: ""
        };
    },
    computed: {
        filteredReviews() {
            let r = this.selectedRating
            if (!r) {
                return this.reviews;
            }
            return this.reviews.filter((review) => review.Rating === r );
        }
    },
    created() {
        const csvContent = `Name,Rating,Comment
Іван,5,Дякую за швидку доставку
Ольга,5,Все супер! Буду замовляти ще
Андрій,5,Обслуговування як завжди - на висоті
Марина,4,Все чудово! Покупкою задоволена але коробка була прим'ята.
Сергій,5,Рекомендую цей чудовий магазин усім!
Данило,5,Дуже демократичні ціни. Я завжди купую лише тут.
Матвій,5,Дякую за подарунок до покупки - завжди радуєте приємними сюрпризами.
Анна,5,Дякую за чудові знижки
Раймонд,4,Як завжди все кльово але малий термін гарантії для годинника хотілося б довше.
`;
        Papa.parse(csvContent.trim(), {
            header: true,
            complete: (result) => {
                this.reviews = result.data; // Зберігаємо розпарсені дані
            },
        });
    },
}

</script>

<style scoped>
h2 {
    text-align: center;
}

table {
    width: 90%;
    margin: 30px auto;
}

th,
td {
    background: #f8f9fa;
    padding: 4px;
}
.comment{
    
    text-align: left;
}

div {
    padding: 1em;
}
</style>