<template>
    <div>
        <h2>Shopping cart</h2>
        <p v-if="cartItems === 0">Cart empty</p>
        <ul class="cart-list">
            <li class="product-card" v-for="(item, index) in cartItems" :key="index">
                <img class="product-image" :src="item.image" :alt="item.name" width="50">

                <div>
                    <p class="info">{{ item.name }}</p>
                    <p class="about">{{ item.name }}</p>
                </div>
                <p class="info price">{{ item.price }}</p>

                <svg class="remove-button" @:click="removeItem(index)" fill="#000000" viewBox="-3.5 0 19 19"
                    xmlns="http://www.w3.org/2000/svg">
                    <g id="SVGRepo_bgCarrier" stroke-width="0"></g>
                    <g id="SVGRepo_tracerCarrier" stroke-linecap="round" stroke-linejoin="round"></g>
                    <g id="SVGRepo_iconCarrier">
                        <path
                            d="M11.383 13.644A1.03 1.03 0 0 1 9.928 15.1L6 11.172 2.072 15.1a1.03 1.03 0 1 1-1.455-1.456l3.928-3.928L.617 5.79a1.03 1.03 0 1 1 1.455-1.456L6 8.261l3.928-3.928a1.03 1.03 0 0 1 1.455 1.456L7.455 9.716z">
                        </path>
                    </g>
                </svg>

            </li>
        </ul>
        <p v-if="cartItems.length > 0" class="total">Total: {{ totalPrice }}</p>
        <hr>
    </div>
</template>


<script>
import { inject } from 'vue';

export default {
    setup() {
        const cartItems = inject("cartItems");
        const totalPrice = inject("totalPrice");
        const removeItem = inject("removeItem");

        return { cartItems, totalPrice, removeItem };
    }
}
</script>

<style scoped>
ul {
    padding: 0;
}

svg {
    width: 2em;
}

.cart-list {
    width: 100%;
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 20px;
    justify-content: center;
}

.product-card {
    display: flex;
    align-items: center;
    justify-content: space-between;
    text-align: center;
    max-width: 100%;
    border: 1px solid #e0e0e0;
    border-radius: 12px;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
}

.product-image {
    width: 20vw;
    height: auto;
    object-fit: cover;
}

.info {
    font-size: 2vw;
    margin: 0;
}

.price {
    /* font-size: 18px; */
    font-weight: bold;
    color: #28a745;
}

