<template>
    <div>
        <h2 class="greet">Admin panel</h2>
        <p class="greet">Greetings, {{ username }}!</p>
        <button class="logout" v-on:click="logout">logout</button>
        <div class="profile-card">
            <img v-if="photo" :src="photo" alt="photo" class="photo">
            <div class="info">
                <p class="name">{{ name }}</p>
                <p class="role">{{ role }}</p>
                <p class="number">{{ number }}</p>
                <p class="email">{{ email }}</p>
                <p class="about">{{ about }}</p>
            </div>
        </div>
    </div>
</template>

<script>
export default {
    data: () => {
        return {
            username: localStorage.getItem("authUser") || "",
            name: "Loading...",
            role: "Loading...",
            number: "Loading...",
            email: "Loading...",
            about: "Loading...",
            photo: "",
        }
    },
    async mounted() {
        try {
            const savedUser = localStorage.getItem("authUser")
            if (savedUser) {
                this.username = savedUser;
            } else {
                this.$router.push("/login");
                return;
            }
            const response = await fetch("/admin.json");
            if (!response.ok) {
                throw new Error("HTTP error " + response.status)
            }
            const users = await response.json();
            const curentUser = users.find(user => user.username === this.username);
            if (curentUser) {
                this.name = curentUser.name;
                this.role = curentUser.role;
                this.number = curentUser.number;
                this.email = curentUser.email;
                this.about = curentUser.about;
                this.photo = curentUser.photo || "default-user.png";
            } else {
                console.warn("user not found")
            }



        } catch (error) {
            console.error("Failed loading JSON file:", error)
        }
    },
    methods: {
        logout() {
            localStorage.removeItem("authUser")
            this.$router.push("/")
        }
    }
}
</script>

<style scoped>
h2 {
    margin: 0.2em;
}

p {
    margin: 0;
    padding: 0;
}

.greet {
    margin: 0.4em;
}

.profile-card {
    display: flex;
    margin: 10px;
    gap: 1em;
    justify-self: start;
    align-items: flex-start;
}

.logout {
    position: sticky;
    top: 0;
    z-index: 10;
    display: flex;
    justify-self: end;
    /* position: absolute;
    right: 3vw;
    top: 10rem; */

    background: #26acd9;
    color: #fff;
    font-weight: bold;
    border: none;
    border-radius: 6px;
    padding: 5px 10px;
    cursor: pointer;
    margin-bottom: 20px;
}

.photo {
    width: 20vw;
    /* aspect-ratio: 1/1; */
}

.info {
    display: flex;
    flex-direction: column;
    align-items: start;
    gap: 0.3em;
}
</style>