<template>
    <div class="product-card">
        <img class="product-image" :src="image" :alt="name">
        <h2>{{ name }}</h2>
        <p>{{ description }}</p>
        <p class="price">{{ price }}</p>
        <button class="buy-button" v-on:click="handleAddToCart">Add to cart</button>
    </div>
</template>


<script>
import { inject } from 'vue';

export default {
    setup(props) {
        const addToCart = inject("addToCart");

        function handleAddToCart() {
            addToCart({
                name: props.name,
                price: props.price,
                image: props.image
            })
        }

        return { handleAddToCart }
    },
    props: {
        name: String,
        description: String,
        price: Number,
        image: String
    },
}
</script>


<style scoped>
.product-card {
    width: fit-content;
    border: 1px solid #e0e0e0;
    border-radius: 12px;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
    text-align: center;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
}

.product-image {
    width: 100%;
    object-fit: cover;
}

.price {
    font-size: 18px;
    font-weight: bold;
    color: #1DC99E;
}

.buy-button {
    background: #26acd9;
    color: #fff;
    font-weight: bold;
    border: none;
    border-radius: 6px;
    padding: 10px 20px;
    cursor: pointer;
    margin-bottom: 20px;
}

.buy-button:hover {
    background: #229bc3;
}

h2 {
    margin: 0 1em;
}

@media (min-width: 1024px ) {
    .product-card{
        flex-basis: calc(33.33% - 20px);
        max-width: calc(33.33% - 20px);
    }
}

@media (max-width: 1024px ) and (min-width: 768px ){
    .product-card{
        flex-basis: calc(50% - 20px);
        max-width: calc(50% - 20px);
    }
}

@media (max-width: 768px ){
    .product-card{
        flex-basis: calc(100%);
        max-width: calc(100%);
    }
    header{
        padding: 15px;
    }
}
</style>